class Solution:
    def maximumPopulation(self, logs: list[list[int]]) -> int:
        best_year = 1900
        best_pop = -1
        for year in range(1900, 2101):
            pop = 0
            for birth, death in logs:
                if birth <= year < death:
                    pop += 1
            if pop > best_pop:
                best_pop = pop
                best_year = year
        return best_year

