class Solution:
    def maximumPopulation(self, logs: list[list[int]]) -> int:
        events = []
        for birth, death in logs:
            events.append((birth, 1))
            events.append((death, -1))
        events.sort()
        pop = 0
        best_pop = -1
        best_year = 1900
        i = 0
        while i < len(events):
            year = events[i][0]
            while i < len(events) and events[i][0] == year:
                pop += events[i][1]
                i += 1
            if pop > best_pop:
                best_pop = pop
                best_year = year
        return best_year

