class Solution:
    def maximumPopulation(self, logs: list[list[int]]) -> int:
        base = 1900
        diff = [0] * 202
        for birth, death in logs:
            diff[birth - base] += 1
            diff[death - base] -= 1
        pop = 0
        best_pop = -1
        best_year = base
        for offset in range(201):
            pop += diff[offset]
            if pop > best_pop:
                best_pop = pop
                best_year = base + offset
        return best_year

